-cia-matrix" aria-label="Matriks risiko CIA 5 x 5"><thead><tr><th>Kemungkinan / Dampak</th><th>Sangat rendah (1)</th><th>Rendah (2)</th><th>Sedang (3)</th><th>Tinggi (4)</th><th>Sangat tinggi (5)</th></tr></thead><tbody><tr><th>Sangat sering (5)</th><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="5-1">Medium (5)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="5-2">Medium (10)</td><td data-translate-ui class="rm-cia-high" data-rm-cia-cell="5-3">High (15)</td><td data-translate-ui class="rm-cia-high" data-rm-cia-cell="5-4">High (20)</td><td data-translate-ui class="rm-cia-high" data-rm-cia-cell="5-5">High (25)</td></tr><tr><th>Sering (4)</th><td data-translate-ui class="rm-cia-low" data-rm-cia-cell="4-1">Low (4)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="4-2">Medium (8)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="4-3">Medium (12)</td><td data-translate-ui class="rm-cia-high" data-rm-cia-cell="4-4">High (16)</td><td data-translate-ui class="rm-cia-high" data-rm-cia-cell="4-5">High (20)</td></tr><tr><th>Mungkin (3)</th><td data-translate-ui class="rm-cia-low" data-rm-cia-cell="3-1">Low (3)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="3-2">Medium (6)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="3-3">Medium (9)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="3-4">Medium (12)</td><td data-translate-ui class="rm-cia-high" data-rm-cia-cell="3-5">High (15)</td></tr><tr><th>Jarang (2)</th><td data-translate-ui class="rm-cia-low" data-rm-cia-cell="2-1">Low (2)</td><td data-translate-ui class="rm-cia-low" data-rm-cia-cell="2-2">Low (4)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="2-3">Medium (6)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="2-4">Medium (8)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="2-5">Medium (10)</td></tr><tr><th>Sangat jarang (1)</th><td data-translate-ui class="rm-cia-low" data-rm-cia-cell="1-1">Low (1)</td><td data-translate-ui class="rm-cia-low" data-rm-cia-cell="1-2">Low (2)</td><td data-translate-ui class="rm-cia-low" data-rm-cia-cell="1-3">Low (3)</td><td data-translate-ui class="rm-cia-low" data-rm-cia-cell="1-4">Low (4)</td><td data-translate-ui class="rm-cia-medium" data-rm-cia-cell="1-5">Medium (5)</td></tr></tbody></table></div></details></fieldset><div class="risk-register-grid"><label>Risk ID<input id="rmRiskId" required placeholder="CSR - 004"></label><label>Risk category<input id="rmRiskCategory" required></label><label>Effected asset<input id="rmEffectedAsset" required></label><label>Nama perangkat<select id="rmDeviceName" required><option value="">Select device</option></select></label><label>Risk owner<input id="rmRiskOwner"></label><label>Treatment action<select id="rmTreatmentAction"><option value="">Unassigned</option><option>Acceptance</option><option>Mitigation</option><option>Transfer</option><option>Avoidance</option><option>Closed</option></select></label><label>Deadline<input id="rmDeadline" type="date"></label><label>Owner of action<input id="rmOwnerOfAction"></label><label>Residual likelihood<input id="rmResidualLikelihood" type="number" min="1" max="5"></label><label>Residual impact<input id="rmResidualImpact" type="number" min="1" max="5"></label><label>Residual rating<input id="rmResidualRating" readonly placeholder="Auto from residual score"></label><label>REF<input id="rmRef"></label><label>Acceptance form number<input id="rmAcceptanceFormNo"></label></div>
